// V2 workplace equipment catalog and lifecycle. Prices/effects are game scenario values.
export const EQUIPMENT_GROUPS = Object.freeze([
 {id:'office-pc',label:'PC & Beschaffung',workplace:'Büro / Beschaffung',base:650,life:3,kind:'PC-Arbeitsplatz',effects:['procurement','admin']},
 {id:'office-furniture',label:'Schreibtisch & Büro',workplace:'Büro / Angebots- und Rechnungswesen',base:240,life:13,kind:'Büroausstattung',effects:['quotes','invoicing']},
 {id:'marketing',label:'Marketing & Kundenkontakt',workplace:'Büro / Marketing',base:180,life:8,kind:'Büroausstattung',effects:['marketing','quotes']},
 {id:'workbench',label:'Werkbank & Spannmittel',workplace:'Werkstatt',base:420,life:14,kind:'Werkstattausstattung',effects:['production','quality']},
 {id:'hand-tools',label:'Handwerkzeug',workplace:'Werkstatt',base:90,life:8,kind:'Werkzeug',effects:['production','quality']},
 {id:'special-tools',label:'Spezialwerkzeug',workplace:'Werkstatt / auftragsbezogen',base:850,life:8,kind:'Spezialwerkzeug',effects:['production','quality'],leaseable:true},
 {id:'ppe',label:'PSA & Arbeitsschutz',workplace:'Werkstatt',base:110,life:5,kind:'Arbeitsschutz',effects:['safety','production']},
 {id:'storage',label:'Lagerregale & Behälter',workplace:'Lager',base:320,life:14,kind:'Lagereinrichtung',effects:['storage','procurement']},
 {id:'handling',label:'Lager- und Fördertechnik',workplace:'Lager / Versand',base:560,life:8,kind:'Fördermittel',effects:['storage','shipping']},
 {id:'shipping',label:'Verpackungs- und Versandplatz',workplace:'Lager / Versand',base:260,life:13,kind:'Versandausstattung',effects:['shipping','admin']}
]);
const names=['Einstieg','Kompakt','Standard','Ergonomie','Robust','Profi','Präzision','Effizienz','Premium','Industrie'];
export const EQUIPMENT_CATALOG=Object.freeze(EQUIPMENT_GROUPS.flatMap(group=>names.map((name,i)=>({id:`${group.id}-${i+1}`,groupId:group.id,name:`${group.label} · ${name}`,workplace:group.workplace,price:Math.round(group.base*(1+i*.48)),usefulLifeYears:group.life,kind:group.kind,condition:100,wearPerWorkday:group.effects.includes('production')?0.045+i*.003:0.018+i*.001,capacityBonus:group.id==='storage'?i*4:0,bonus:Object.fromEntries(group.effects.map((k,j)=>[k,Number((.015+i*.009+j*.004).toFixed(3))])),leaseable:Boolean(group.leaseable),leaseMonthly:group.leaseable?Math.round(group.base*(.08+i*.012)):0,financeable:true,source:'scenario'}))));
const cents=n=>Math.round((Number(n)||0)*100)/100;
export function ensureEquipmentState(game,finance){game.assets||=[];game.equipmentLeases||=[];finance.equipmentLoans||=[];finance.equipmentDepreciationByMonth||={};for(const asset of game.assets){asset.purchasePrice??=Number(asset.bookValue)||0;asset.bookValue??=asset.purchasePrice;asset.condition??=100;asset.usefulLifeYears??=8;asset.wearPerWorkday??=.02;asset.acquiredAt??=game.date;asset.bonus||={};}if(game.ownerToolKit&&!game.assets.some(x=>x.id==='starter-workbench'||x.name===game.ownerToolKit.name)){game.assets.push({id:'starter-workbench',catalogId:null,name:game.ownerToolKit.name||'Werkbank und Handwerkzeug',groupId:'workbench',kind:'Werkstattausstattung',workplace:'Werkstatt',purchasePrice:Number(game.ownerToolKit.bookValue)||350,bookValue:Number(game.ownerToolKit.bookValue)||350,condition:100,usefulLifeYears:14,wearPerWorkday:.025,capacityBonus:0,bonus:{production:.025},acquiredAt:game.date,lastDepreciationMonth:null});}}
export function availableEquipmentCredit(finance){const gross=Number(finance.overdraftLimit)||0,used=(Number(finance.overdraftDrawn)||0)+(Number(finance.propertyLoan?.balance)||0)+(Number(finance.machineLoan)||0)+(Number(finance.openingPayables)||0)+(Number(finance.unpaidCosts)||0)+(finance.equipmentLoans||[]).reduce((n,x)=>n+Number(x.balance||0),0);return cents(Math.max(0,gross-used));}
export function buyEquipment(game,finance,catalogId,{installments=false,date=game.date}={}){ensureEquipmentState(game,finance);const item=EQUIPMENT_CATALOG.find(x=>x.id===catalogId);if(!item)return {ok:false,reason:'Auswahl nicht gefunden'};let financed=0;if(item.price>finance.cash){if(!installments)return {ok:false,reason:'Nicht genug Bankguthaben'};financed=cents(item.price-finance.cash);const cap=availableEquipmentCredit(finance);if(financed>cap)return {ok:false,reason:`Finanzierungsrahmen ${cap.toFixed(2)} € reicht nicht`};}const down=cents(item.price-financed);finance.cash=cents(finance.cash-down);if(down)finance.cashMovements.push({date,kind:'ANLAGEKAUF',amount:-down,reference:item.id});const immediateExpense=item.price<=800,asset={...item,bookValue:immediateExpense?0:item.price,accountingTreatment:immediateExpense?'GWG-Sofortaufwand':'lineare AfA nach Szenario-Nutzungsdauer',purchasePrice:item.price,condition:100,acquiredAt:date,lastDepreciationMonth:null};game.assets.push(asset);if(immediateExpense){finance.expenses.push({date,type:'ANLAGE_AUFWAND',label:item.name,amount:item.price,paidAt:date});finance.events.push({date,phase:1,kind:'GWG_AUFWAND',text:`${item.name}: ${item.price} € im GWG-Szenario sofort als Aufwand erfasst; physischer Zustand bleibt separat erhalten.`});}if(financed){const months=12,rate=.08/12,payment=cents(financed*rate/(1-Math.pow(1+rate,-months))),first=new Date(`${date.slice(0,7)}-01T12:00:00Z`);first.setUTCMonth(first.getUTCMonth()+1);let last=new Date(Date.UTC(first.getUTCFullYear(),first.getUTCMonth()+1,0));while(last.getUTCDay()===0||last.getUTCDay()===6)last.setUTCDate(last.getUTCDate()-1);finance.equipmentLoans.push({id:`EQ-${item.id}-${date}`,assetId:asset.id,principal:financed,balance:financed,monthsRemaining:months,monthlyPayment:payment,rate:.08,nextDueDate:last.toISOString().slice(0,10)});}finance.events.push({date,phase:1,kind:'BETRIEBSMITTEL_KAUF',text:`${item.name} für ${item.price} € erworben${financed?`; Ratenkauf ${financed.toFixed(2)} € über 12 Monate`:' aus Bankguthaben'}.`});return {ok:true,asset,financed};}
export function leaseSpecialTool(game,finance,catalogId,months=1){ensureEquipmentState(game,finance);const item=EQUIPMENT_CATALOG.find(x=>x.id===catalogId&&x.leaseable);if(!item)return {ok:false,reason:'Nur Spezialwerkzeuge sind mietbar'};if(game.equipmentLeases.some(x=>x.catalogId===catalogId&&x.status==='ACTIVE'))return {ok:false,reason:'Dieses Spezialwerkzeug ist bereits gemietet'};const lease={id:`LEASE-${catalogId}-${game.date}`,catalogId,name:item.name,monthlyRate:item.leaseMonthly,startedAt:game.date,months:Math.max(1,Math.min(12,Number(months)||1)),status:'ACTIVE',condition:100,wearPerWorkday:item.wearPerWorkday,bonus:item.bonus,groupId:item.groupId};game.equipmentLeases.push(lease);finance.events.push({date:game.date,phase:1,kind:'SPEZIALWERKZEUG_MIETE',text:`${item.name} für ${lease.monthlyRate} €/Monat gemietet.`});return {ok:true,lease};}
export function equipmentEffects(game){const active=[...(game.assets||[]).filter(x=>x.condition>0),...(game.equipmentLeases||[]).filter(x=>x.status==='ACTIVE')],out={production:0,quality:0,procurement:0,admin:0,quotes:0,invoicing:0,marketing:0,safety:0,storage:0,shipping:0};for(const item of active){const wear=Math.max(.35,Number(item.condition||100)/100);for(const [key,value] of Object.entries(item.bonus||{}))out[key]=(out[key]||0)+Number(value||0)*wear;}for(const x of Object.keys(out))out[x]=Math.min(.25,out[x]);return out;}
export function equipmentSatisfiesTool(game,toolId){if(!toolId)return false;const owned=(game.assets||[]).filter(x=>x.condition>0);if(toolId==='bench-clamp-set')return owned.some(x=>x.groupId==='workbench');if(toolId==='cnc-metrology-kit')return owned.some(x=>x.groupId==='special-tools'&&x.condition>0);return false;}
export function advanceEquipmentDay(game,finance,date){ensureEquipmentState(game,finance);const month=date.slice(0,7),weekday=new Date(`${date}T12:00:00Z`).getUTCDay(),working=weekday!==0&&weekday!==6,worked=game.workLog?.some(x=>x.date===date);if(working)for(const a of game.assets)a.condition=Math.max(0,cents(a.condition-(a.wearPerWorkday||.02)));if(worked)for(const a of game.equipmentLeases.filter(x=>x.status==='ACTIVE'))a.condition=Math.max(0,cents(a.condition-(a.wearPerWorkday||.03)));for(const a of game.assets){const acquisition=new Date(`${a.acquiredAt||date}T12:00:00Z`),current=new Date(`${date}T12:00:00Z`);if(a.lastDepreciationMonth===month||acquisition>current)continue;const acquiredMonth=acquisition.getUTCMonth(),periodMonths=acquisition.getUTCFullYear()===current.getUTCFullYear()&&acquiredMonth===current.getUTCMonth()?12-acquiredMonth:1,annual=cents(Number(a.purchasePrice||0)/Math.max(1,Number(a.usefulLifeYears)||1)),amount=cents(annual*periodMonths/12),depreciation=Math.min(Number(a.bookValue)||0,amount);a.bookValue=cents(Math.max(0,(Number(a.bookValue)||0)-depreciation));a.lastDepreciationMonth=month;if(depreciation){finance.equipmentDepreciationByMonth[month]=cents((finance.equipmentDepreciationByMonth[month]||0)+depreciation);finance.events.push({date,phase:10,kind:'AFA_ANLAGE',text:`AfA ${a.name}: ${depreciation.toFixed(2)} €; Restbuchwert ${a.bookValue.toFixed(2)} € (Nutzungsdauer ${a.usefulLifeYears} Jahre).`});}}for(const lease of game.equipmentLeases.filter(x=>x.status==='ACTIVE')){const start=new Date(`${lease.startedAt}T12:00:00Z`),expires=new Date(start);expires.setUTCMonth(expires.getUTCMonth()+lease.months);if(currentDate(date)>=expires.toISOString().slice(0,10))lease.status='RETURNED';}}
function currentDate(date){return date;}
export function processEquipmentInstallments(game,finance,date){ensureEquipmentState(game,finance);for(const loan of finance.equipmentLoans){if(loan.balance<=0)continue;const due=loan.nextDueDate||date;if(due>date)continue;const interest=cents(loan.balance*loan.rate/12),payment=cents(Math.min(loan.balance+interest,loan.monthlyPayment)),principal=cents(payment-interest);if(finance.cash<payment){loan.retryFailures=(loan.retryFailures||0)+1;loan.nextDueDate=`${new Date(new Date(`${date}T12:00:00Z`).getTime()+7*86400000).toISOString().slice(0,10)}`;finance.events.push({date,phase:8,kind:'ANLAGENRATE_FEHLGESCHLAGEN',text:`Anlagenrate ${payment.toFixed(2)} € mangels Guthaben offen; neuer Versuch ${loan.nextDueDate}.`});continue;}finance.cash=cents(finance.cash-payment);finance.cashMovements.push({date,kind:'ANLAGENRATE',amount:-payment,reference:loan.id});loan.balance=cents(Math.max(0,loan.balance-principal));loan.monthsRemaining=Math.max(0,loan.monthsRemaining-1);finance.equipmentInterestByMonth||={};finance.equipmentInterestByMonth[date.slice(0,7)]=cents((finance.equipmentInterestByMonth[date.slice(0,7)]||0)+interest);const next=new Date(`${date.slice(0,7)}-01T12:00:00Z`);next.setUTCMonth(next.getUTCMonth()+1);const last=new Date(Date.UTC(next.getUTCFullYear(),next.getUTCMonth()+1,0));while(last.getUTCDay()===0||last.getUTCDay()===6)last.setUTCDate(last.getUTCDate()-1);loan.nextDueDate=loan.balance?last.toISOString().slice(0,10):null;finance.events.push({date,phase:8,kind:'ANLAGENRATE',text:`Anlagenrate ${payment.toFixed(2)} € (${principal.toFixed(2)} € Tilgung, ${interest.toFixed(2)} € Zins); Restschuld ${loan.balance.toFixed(2)} €.`});}}
